+///|
+fn server_env_value(value : String, root : String) -> String raise {
+  let result = StringBuilder()
+  let mut remaining = value
+  while remaining.split_once("${") is Some((prefix, expression)) {
+    result.write_string(quote(prefix.to_owned()))
+    guard expression.split_once("}") is Some((variable, suffix)) else {
+      raise AdapterError("Invalid saved server environment reference")
+    }
+    let reference = variable.to_owned()
+    let required = reference.has_suffix("?")
+    let name = if required {
+      reference[:reference.length() - 1].to_owned()
+    } else {
+      reference
+    }
+    ignore(
+      interpolate("${" + reference + "}", _ => Some(""), "server environment"),
+    )
+    if name == "DEVSY_REMOTE_WORKSPACE_FOLDER" {
+      result.write_string(quote(root))
+    } else {
+      result.write_string(
+        "\"${" + name + (if required { "?" } else { "-" }) + "}\"",
+      )
+    }
+    remaining = suffix.to_owned()
+  }
+  result.write_string(quote(remaining))
+  result.to_string()
+}
